/** Source-bound city reducer. No file or Progress writer; the original Result owns commit. */
public final class StoryCityPolicy {
 private StoryCityPolicy() {}
 private static final String NS="q7StoryCity", HASH="af2328b97372c27fd392b5b399d03daa17fa73acdd35d2b1ad5b0a8f07218069";
 /** Policy opt-in for menus whose handoff city effects are not yet declared in the shared catalog. */
 private static final Set<Integer> UNCLAIMED_MENUS=Collections.unmodifiableSet(new HashSet<>(Arrays.asList(2)));
 private static final String[] FIELDS={"areaFree","areaFight","areaLock","areaUnlock"};
 private static final String FALL="areaFall",CR7="areaCR7",CORE="q7ChapterCore";
 private static final Set<String> KINDS=Collections.unmodifiableSet(new HashSet<>(Arrays.asList("normal","virtual","auxiliary")));
 private static final Map<Integer,Integer> ENTRY_FIGHT_RELEASE=Collections.unmodifiableMap(new HashMap<Integer,Integer>(){{put(1443,6);put(1445,4);}});
 private static final Map<Integer,String> ENTRY_ROUTES=Collections.unmodifiableMap(new HashMap<Integer,String>(){{put(1424,"27-1");}});
 private static volatile Catalog catalog;
 private static volatile LocalEventCatalog graph;
 private static final class Chapter {int area;String route;List<List<Integer>> groups;List<Integer> scenes;}
 /* Area fields are reduced here; hero fields stay owned by the original fixed engine. */
 private static final Set<String> HERO_FIELDS=Collections.unmodifiableSet(new LinkedHashSet<>(Arrays.asList("cineLockHeroes","banHeroes","recoverBanHeroes")));
 private static final class Effect {final Map<String,List<Integer>> areas;final List<Integer> fall,cr7;final boolean heroes;Effect(Map<String,List<Integer>>a,List<Integer>f,List<Integer>c,boolean h){areas=a;fall=f;cr7=c;heroes=h;}}
 private static final class Catalog {
  final Set<Integer> areas=new HashSet<>(),virtual=new HashSet<>(),menus=new HashSet<>(),ready=new HashSet<>();
  final Set<String> routes=new HashSet<>();
  final Map<Integer,Map<String,List<Integer>>> effects=new HashMap<>();
  final Map<String,Chapter> chapters=new HashMap<>();
  final Map<Integer,Integer> sceneAreas=new HashMap<>();
  final Map<Integer,List<Integer>> parties=new HashMap<>();
  final Map<Integer,Map<String,List<Integer>>> requirements=new HashMap<>();
  final Map<Integer,String> kinds=new HashMap<>();
 }
 public static void prepare(Context context)throws IOException {
  try(InputStream in=context.getAssets().open("project7_story_city/catalog-v1.json.gz")) {
   byte[] packed=read(in,1000000);if(!hex(MessageDigest.getInstance("SHA-256").digest(packed)).equals(HASH))throw new IOException("Story city asset hash");
   byte[] raw;try(GZIPInputStream zip=new GZIPInputStream(new ByteArrayInputStream(packed))){raw=read(zip,4000000);}
   JSONObject root=new JSONObject(new String(raw,"US-ASCII"));if(!root.getString("schema").equals("project7-story-city-v1"))throw new IOException("Story city schema");Catalog c=new Catalog();
   JSONArray aa=root.getJSONArray("areas");for(int i=0;i<aa.length();i++){JSONObject a=aa.getJSONObject(i);int id=a.getInt("id");if(!c.areas.add(id))throw new IOException("Duplicate city");String kind=a.getString("kind");if(!KINDS.contains(kind))throw new IOException("Unknown city area kind");c.kinds.put(id,kind);if(kind.equals("virtual"))c.virtual.add(id);JSONObject req=a.getJSONObject("raw").optJSONObject("area_require");Map<String,List<Integer>> rr=new HashMap<>();if(req!=null)for(Iterator<String>k=req.keys();k.hasNext();){String key=k.next();rr.put(key,ints(req.getJSONArray(key)));}c.requirements.put(id,Collections.unmodifiableMap(rr));}
   c.menus.addAll(ints(root.getJSONArray("scope_menus")));c.ready.addAll(ints(root.getJSONArray("public_ready_ids")));JSONArray routes=root.getJSONArray("route_keys");for(int i=0;i<routes.length();i++)c.routes.add(routes.getString(i));
   JSONArray chapters=root.getJSONArray("chapters");for(int i=0;i<chapters.length();i++){JSONObject row=chapters.getJSONObject(i);Chapter ch=new Chapter();ch.area=row.getInt("area");ch.route=row.getString("route");ch.groups=new ArrayList<>();ch.scenes=new ArrayList<>();JSONArray groups=row.getJSONArray("groups");if(groups.length()!=10||!c.areas.contains(ch.area)||!c.routes.contains(ch.route))throw new IOException("Chapter closure");for(int j=0;j<10;j++){List<Integer>g=ints(groups.getJSONArray(j));if(g.size()>1)throw new IOException("Chapter group");ch.groups.add(g);ch.scenes.addAll(g);}if(ch.scenes.isEmpty()||c.chapters.put(ch.area+":"+ch.route,ch)!=null)throw new IOException("Chapter duplicate");if(c.virtual.contains(ch.area)||ch.route.startsWith("27-"))for(int scene:ch.scenes){Integer old=c.sceneAreas.put(scene,ch.area);if(old!=null&&old!=ch.area)throw new IOException("Scene collision");}}
   JSONObject missions=root.getJSONObject("missions");for(Iterator<String>ks=missions.keys();ks.hasNext();){String key=ks.next();JSONObject row=missions.getJSONObject(key);String kind=row.getString("kind");if(kind.equals("virtual")||kind.equals("coc")){int scene=Integer.parseInt(key);if(!Integer.valueOf(row.getInt("area")).equals(c.sceneAreas.get(scene))||row.getInt("wire")!=1)throw new IOException("Virtual/COC mission closure");List<Integer> party=ints(row.getJSONArray("party"));if(party.isEmpty()||party.size()!=row.getInt("minimum")||party.size()!=row.getInt("maximum"))throw new IOException("Virtual/COC cast");c.parties.put(scene,party);}}
   JSONObject effects=root.getJSONObject("effects");for(Iterator<String>ks=effects.keys();ks.hasNext();){String key=ks.next();JSONObject row=effects.getJSONObject(key);Map<String,List<Integer>> values=new LinkedHashMap<>();for(String field:FIELDS){List<Integer>ids=row.has(field)?ints(row.getJSONArray(field)):Collections.<Integer>emptyList();if(!c.areas.containsAll(ids))throw new IOException("Effect reference");values.put(field,ids);}c.effects.put(Integer.valueOf(key),Collections.unmodifiableMap(values));}
   catalog=c;graph=new LocalEventCatalog(context);StoryMainlineEntry.prepare(context);
  }catch(IOException e){throw e;}catch(Exception e){throw new IOException("Story city fixed catalog",e);}
 }
 private static byte[]read(InputStream in,int limit)throws IOException {ByteArrayOutputStream b=new ByteArrayOutputStream();byte[]buf=new byte[8192];for(int n;(n=in.read(buf))!=-1;){if(b.size()>limit-n)throw new IOException("Story city bound");b.write(buf,0,n);}return b.toByteArray();}
 private static String hex(byte[]b){StringBuilder s=new StringBuilder();for(byte v:b)s.append(String.format(java.util.Locale.ROOT,"%02x",v&255));return s.toString();}
 private static List<Integer>ints(JSONArray a)throws JSONException {List<Integer>x=new ArrayList<>();Set<Integer>seen=new HashSet<>();for(int i=0;i<a.length();i++){Object v=a.get(i);if(!(v instanceof Integer)||(Integer)v<0||!seen.add((Integer)v))throw new JSONException("Integer reference");x.add((Integer)v);}return Collections.unmodifiableList(x);}
 private static byte[]doc(byte[]p,String key){byte[]b=BsonLite.documentValue(p,key);return b==null?BsonLite.EMPTY_DOCUMENT:b;}
 private static String route(byte[]p){return BsonLite.stringValue(doc(p,"std"),"rt");}
 private static boolean legacy(byte[]p){String rt=route(p);Integer menu=BsonLite.intValue(p,"q7ChapterMenu");return menu!=null&&menu.intValue()==11||rt!=null&&(rt.equals("12")||rt.startsWith("12-"));}
 private static boolean dedicated(byte[]p){Catalog c=catalog;if(c==null||p==null||legacy(p))return false;Integer menu=BsonLite.intValue(p,"q7ChapterMenu");return menu!=null&&c.menus.contains(menu)||c.routes.contains(route(p))||StoryMainlineEntry.cityOwns(p);}
 /** Unclaimed handoff: only after a committed week transition, never for legacy or dedicated owners. */
 private static boolean unclaimed(byte[]p){Catalog c=catalog;if(c==null||p==null||legacy(p)||BsonLite.keys(doc(p,"q7WeekTransition")).isEmpty())return false;Integer menu=BsonLite.intValue(p,"q7ChapterMenu");return menu!=null&&UNCLAIMED_MENUS.contains(menu)&&!dedicated(p);}
 /** Adopt only an event that declares this exact active route; dedicated AN lock events stay with their owner. */
 private static boolean unclaimedEffect(int event,byte[]p,LocalEventCatalog events){String target=events.routes.get(Integer.valueOf(event));return target!=null&&target.equals(route(p))&&!LocalAnCityEngine.LOCK_EVENTS.contains(Integer.valueOf(event));}
 private static boolean owned(byte[]p){return dedicated(p)||unclaimed(p);}
 /** Stable single-owner predicate for the Gateway seam: no throw and no area dependency. */
 public static boolean owns(byte[]profile){return owned(profile);}
 private static void binding(byte[]p,LocalTutorialStore.Progress progress){byte[]b=doc(p,NS);if(!BsonLite.keys(b).isEmpty()&&(!HASH.equals(BsonLite.stringValue(b,"catalog"))||!Objects.equals(progress.weekCommit,BsonLite.stringValue(b,"week"))))throw new IllegalArgumentException("城市周期数据不一致，请重新进入");if(progress.weekCommit==null||progress.weekCommit.isEmpty())throw new IllegalArgumentException("城市周期未准备完成，请重新进入");}
 /** Validate every pending event first; publish exactly one candidate profile assignment. */
 public static void refresh(LocalResourceEngine.Result result,LocalEventCatalog events,LocalTutorialStore.Progress p){
  if(result!=null&&p!=null)StoryMissionBridge.offerMissionOutcomes(p,result.profile,events);
  if(!owned(result.profile)){LocalChapterCityEngine.refresh(result,events,p);return;}
  binding(result.profile,p);Catalog c=catalog;byte[]before=result.profile;byte[]receipts=doc(before,"q7ChapterEffects"),states=doc(before,"q7ChapterStates"),locks=doc(before,"q7ChapterLocks"),owners=doc(before,"q7ChapterLockOwners"),core=doc(before,CORE);Set<Integer>base=new HashSet<>(BsonLite.intArrayValues(before,"q7WeekEventBaseline"));List<Integer>pending=new ArrayList<>();Map<Integer,Effect> pendingEffects=new HashMap<>();Map<Integer,byte[]> pendingHeroes=new HashMap<>();
  for(int event:p.completedEvents){if(base.contains(event)||Boolean.TRUE.equals(BsonLite.boolValue(receipts,Integer.toString(event))))continue;Map<String,List<Integer>>expected=c.effects.get(event);byte[]actual=events.cityEffects.get(event);if(expected==null){if(actual!=null&&(StoryMainlineEntry.cityOwns(before)||(unclaimed(before)&&unclaimedEffect(event,before,events)))){Effect effect=classifyEffect(actual);expected=effect.areas;if(effect.heroes)pendingHeroes.put(event,actual);pendingEffects.put(event,effect);}else if(actual!=null&&hasCity(actual)&&!unclaimed(before))throw new IllegalArgumentException("城市事件尚未支持，请重新进入");else continue;}if(actual==null)throw new IllegalArgumentException("城市事件数据缺失，请重新进入");Effect typed=classifyEffect(actual);if(!typed.areas.equals(expected))throw new IllegalArgumentException("城市事件数据校验失败，请重新进入");if(typed.heroes)pendingHeroes.put(event,actual);pending.add(event);pendingEffects.put(event,typed);}
  for(int event:pending){Effect effect=pendingEffects.get(event);for(int area:effect.areas.get("areaFight"))states=BsonLite.withProfileInt(states,Integer.toString(area),1);for(int area:effect.fall)states=BsonLite.withProfileInt(states,Integer.toString(area),2);for(int area:effect.areas.get("areaFree"))states=BsonLite.withProfileInt(states,Integer.toString(area),0);for(String field:new String[]{"areaLock","areaUnlock"})for(int area:effect.areas.get(field)){String key=Integer.toString(area);locks=BsonLite.withProfileBool(locks,key,field.equals("areaLock"));owners=field.equals("areaLock")?BsonLite.withProfileDocument(owners,key,BsonLite.document("event",event,"week",p.weekCommit,"route",ENTRY_ROUTES.containsKey(event)?ENTRY_ROUTES.get(event):route(before),"v",BsonLite.intValue(doc(owners,key),"v")==null?1:BsonLite.intValue(doc(owners,key),"v")+1)):BsonLite.withoutProfileKey(owners,key);}for(int area:effect.cr7){String key=Integer.toString(area);Integer current=BsonLite.intValue(states,key);states=BsonLite.withProfileInt(states,key,current!=null&&current.intValue()==2?4:3);core=BsonLite.withProfileBool(core,key,true);}receipts=BsonLite.withProfileBool(receipts,Integer.toString(event),true);}
  for(int event:pending){Integer area=ENTRY_FIGHT_RELEASE.get(event);if(area==null)continue;Effect effect=pendingEffects.get(event);if(!effect.areas.get("areaFight").contains(area)||!Boolean.TRUE.equals(BsonLite.boolValue(receipts,"1424"))||hasLaterUnlock(c,event,area))continue;String key=Integer.toString(area);byte[]owner=doc(owners,key);if(BsonLite.intValue(owner,"event")==null||BsonLite.intValue(owner,"event")!=1424||BsonLite.intValue(owner,"v")==null||BsonLite.intValue(owner,"v")!=1||!Objects.equals(p.weekCommit,BsonLite.stringValue(owner,"week"))||!Objects.equals(route(before),BsonLite.stringValue(owner,"route"))||BsonLite.intValue(states,key)==null||BsonLite.intValue(states,key)!=1||!Boolean.TRUE.equals(BsonLite.boolValue(locks,key)))continue;locks=BsonLite.withProfileBool(locks,key,false);owners=BsonLite.withoutProfileKey(owners,key);}
  byte[]candidate=BsonLite.withProfileDocument(before,"q7ChapterEffects",receipts);candidate=BsonLite.withProfileDocument(candidate,"q7ChapterStates",states);candidate=BsonLite.withProfileDocument(candidate,"q7ChapterLocks",locks);candidate=BsonLite.withProfileDocument(candidate,"q7ChapterLockOwners",owners);candidate=BsonLite.withProfileDocument(candidate,NS,BsonLite.document("schema",1,"catalog",HASH,"week",p.weekCommit));if(!BsonLite.keys(core).isEmpty())candidate=BsonLite.withProfileDocument(candidate,CORE,core);
  // Non-area hero types stay with the original fixed engine; a failure publishes nothing.
  result.profile=candidate;int replies=result.replies.size();
  try{for(int event:pending)if(pendingHeroes.containsKey(event))LocalChapterCityEngine.applyHeroes(result,pendingHeroes.get(event));}
  catch(RuntimeException error){result.profile=before;while(result.replies.size()>replies)result.replies.remove(result.replies.size()-1);throw error;}
  byte[]current=result.profile;
  // Projection is in the same profile candidate and consumed by the original CityData protocol.
  byte[]city=doc(current,"city"),areas=doc(city,"areas");byte[]reply=allAreaInfoReplyDocument(true,p,current),ais=doc(reply,"ais");for(String key:BsonLite.keys(ais))areas=BsonLite.withProfileDocument(areas,key,doc(ais,key));candidate=BsonLite.withProfileDocument(current,"city",BsonLite.withProfileDocument(city,"areas",areas));
  result.profile=candidate;if(!Arrays.equals(before,candidate))result.add("get_all_area_info_reply",reply);
 }
 private static boolean hasCity(byte[]x){for(String f:FIELDS)if(!strictArray(x,f).isEmpty())return true;return false;}
 /** Single typed split: area fields are ours, hero fields remain the original engine's, unknown rejects. */
 private static Effect classifyEffect(byte[]x){Map<String,List<Integer>>values=new LinkedHashMap<>();List<Integer>fall=Collections.emptyList(),cr7=Collections.emptyList();boolean any=false,heroes=false;for(String key:BsonLite.keys(x)){if(Arrays.asList(FIELDS).contains(key)||key.equals(FALL)||key.equals(CR7)){List<Integer>ids=strictArray(x,key);if(key.equals(FALL))fall=ids;else if(key.equals(CR7))cr7=ids;else values.put(key,ids);any|=!ids.isEmpty();}else if(HERO_FIELDS.contains(key)){strictInts(x,key);heroes=true;}else if(key.equals("friendly"))throw new IllegalArgumentException("友情事件由原引擎持有，暂不支持");else throw new IllegalArgumentException("城市事件字段尚未支持，请重新进入");}for(String field:FIELDS)if(!values.containsKey(field))values.put(field,Collections.<Integer>emptyList());if(!any&&!heroes)throw new IllegalArgumentException("城市事件数据缺失，请重新进入");return new Effect(Collections.unmodifiableMap(values),fall,cr7,heroes);}
 private static List<Integer>strictInts(byte[]x,String f){byte[]a=BsonLite.arrayValue(x,f);if(a==null){if(BsonLite.keys(x).contains(f))throw new IllegalArgumentException("城市事件数组格式错误");return Collections.emptyList();}List<Integer>r=new ArrayList<>();for(String k:BsonLite.keys(a)){if(!k.equals(Integer.toString(r.size())))throw new IllegalArgumentException("城市事件数组顺序错误");Number v=BsonLite.numericValue(a,k);if(!(v instanceof Integer))throw new IllegalArgumentException("城市事件数值格式错误");r.add((Integer)v);}return r;}
 private static boolean hasLaterUnlock(Catalog c,int event,int area){for(Map.Entry<Integer,Map<String,List<Integer>>> e:c.effects.entrySet())if(e.getKey()>event&&e.getValue().get("areaUnlock").contains(area))return true;return false;}
 private static List<Integer>strictArray(byte[]x,String f){byte[]a=BsonLite.arrayValue(x,f);if(a==null){if(BsonLite.keys(x).contains(f))throw new IllegalArgumentException("城市事件数组格式错误");return Collections.emptyList();}List<Integer>r=new ArrayList<>();for(String k:BsonLite.keys(a)){if(!k.equals(Integer.toString(r.size())))throw new IllegalArgumentException("城市事件数组顺序错误");Number v=BsonLite.numericValue(a,k);if(!(v instanceof Integer)||!catalog.areas.contains(v)||r.contains(v))throw new IllegalArgumentException("城市事件地区格式错误");r.add((Integer)v);}return r;}
 private static boolean known(int area){return catalog!=null&&catalog.areas.contains(area);}
 /** Pure catalog membership for the query seam; no ownership/profile gate, false before prepare. */
 public static boolean knownArea(int area){return known(area);}
 private static boolean auxiliary(int area){Catalog c=catalog;return c!=null&&"auxiliary".equals(c.kinds.get(area));}
 private static void requireArea(byte[]p,int area){if(owned(p)&&!known(area))throw new IllegalArgumentException("未知城市地区");}
 public static boolean handlesState(byte[]p,int area){if(!owned(p))return false;if(!known(area))throw new IllegalArgumentException("未知城市地区");return true;}
 public static Integer state(byte[]p,int area){if(!handlesState(p,area))return null;Integer value=BsonLite.intValue(doc(p,"q7ChapterStates"),Integer.toString(area));return value;}
 public static boolean locked(byte[]p,int area){return handlesState(p,area)&&(LocalAnCityEngine.active(p)&&LocalAnCityEngine.locked(p,area)||Boolean.TRUE.equals(BsonLite.boolValue(doc(p,"q7ChapterLocks"),Integer.toString(area))));}
 private static Chapter resolve(LocalTutorialStore.Progress p,int area,byte[]profile){if(p==null||!owned(profile))return null;return catalog.chapters.get(area+":"+route(profile));}
 private static boolean battle(LocalTutorialStore.Progress p,int scene){Set<Integer>b=p.eventConditions.get("battle");return b!=null&&b.contains(scene);}
 public static int area(int scene){Catalog c=catalog;Integer area=c==null?null:c.sceneAreas.get(scene);return area==null?StoryMissionBridge.area(scene):area;}
 public static int status(LocalTutorialStore.Progress p,int area,byte[]profile){if(!handlesState(profile,area))return StoryMissionBridge.status(p,area,profile);Integer explicit=state(profile,area);Chapter ch=resolve(p,area,profile);if(ch!=null&&catalog.virtual.contains(area)){if(explicit!=null&&explicit==0)return 0;if(explicit==null){Map<String,List<Integer>> req=catalog.requirements.get(area);List<Integer> ids=req.get(route(profile));if(ids==null)ids=req.get("-1");if(ids==null||ids.isEmpty()||ids.contains(0))return 2;for(int id:ids)if(status(p,id,profile)!=0||locked(profile,id))return 2;}return battle(p,ch.scenes.get(ch.scenes.size()-1))?0:1;}if(auxiliary(area))return explicit!=null?explicit.intValue():2;if(explicit!=null)return explicit.intValue();return StoryMissionBridge.status(p,area,profile);}
 public static byte[]mapStages(LocalTutorialStore.Progress p,int area,byte[]profile){requireArea(profile,area);Chapter ch=resolve(p,area,profile);if(ch==null){if(owned(profile)&&auxiliary(area))return BsonLite.EMPTY_DOCUMENT;return StoryMissionBridge.mapStages(p,area,profile);}if(status(p,area,profile)!=1||locked(profile,area))return BsonLite.EMPTY_DOCUMENT;int current=0;for(int s:ch.scenes)if(!battle(p,s)){current=s;break;}return BsonLite.document("cs",current,"sl",ch.groups);}
 public static byte[]stages(LocalTutorialStore.Progress p,int area,byte[]profile){if(!handlesState(profile,area))return StoryMissionBridge.stages(p,area,profile);if(locked(profile,area)||auxiliary(area))return BsonLite.EMPTY_DOCUMENT;return mapStages(p,area,profile);}
 public static boolean consumeVictory(LocalTutorialStore.Progress p,byte[]profile,int type,int scene){Integer area=catalog==null?null:catalog.sceneAreas.get(scene);if(area==null)return StoryMissionBridge.consumeVictory(p,profile,type,scene);if(type!=1||battle(p,scene)||!Integer.valueOf(scene).equals(BsonLite.intValue(stages(p,area,profile),"cs")))return false;return StoryMissionBridge.consumeVictory(p,profile,type,scene);}
 public static boolean partyAllowed(byte[]params){Integer scene=BsonLite.intValue(params,"s");List<Integer>party=catalog==null?null:catalog.parties.get(scene);if(party==null)return StoryMissionBridge.partyAllowed(params);if(!Integer.valueOf(1).equals(BsonLite.intValue(params,"t"))||!catalog.sceneAreas.get(scene).equals(BsonLite.intValue(doc(params,"d"),"a")))return false;byte[]h=BsonLite.arrayValue(params,"h");if(h==null||BsonLite.keys(h).size()!=party.size())return false;for(int i=0;i<party.size();i++){Number v=BsonLite.numericValue(h,Integer.toString(i));if(!(v instanceof Integer)||!party.get(i).equals(v))return false;}return true;}
 public static boolean supports(int menu){Catalog c=catalog;if(c!=null&&c.ready.contains(menu))return true;if(menu==StoryMenuEntryData.MENU)return StoryMenuEntryData.ready(menu);if(StoryMainlineEntry.capability(menu))return true;return LocalStoryEntryPolicy.q7OriginalSupports(menu);}
 /** Tail cleanup only: remove this additive binding; original Week reset owns canonical keys. */
 public static byte[]resetProfile(byte[]profile){if(profile==null)return null;return BsonLite.withoutProfileKey(BsonLite.withoutProfileKey(profile,NS),CORE);}
 public static byte[]allAreaInfoReplyDocument(boolean unlocked,LocalTutorialStore.Progress p,byte[]profile){if(unlocked&&p!=null&&profile!=null)StoryMissionBridge.offerMissionOutcomes(p,profile,graph);byte[]reply=BsonLite.q7OriginalAllAreaInfoReplyDocument(unlocked,p,profile);if(!unlocked||!owned(profile)||p==null)return reply;byte[]ais=doc(reply,"ais");for(int area:catalog.areas){String key="area_"+area;byte[]value=doc(ais,key);if(BsonLite.keys(value).isEmpty()){
   // Exact original area wire, replacing all identity-dependent fields (no clamp leakage).
   value=doc(ais,"area_2");value=BsonLite.withProfileInt(value,"id",area);value=BsonLite.withProfileDocument(value,"bd",BsonLite.EMPTY_DOCUMENT);value=BsonLite.withProfileDocument(value,"dbd",BsonLite.EMPTY_DOCUMENT);value=BsonLite.withProfileInt(value,"mbn",0);
  }byte[]st=BsonLite.arrayValue(value,"st");Boolean coreFlag=st==null?false:BsonLite.boolValue(st,"1");Boolean coreOverride=BsonLite.boolValue(doc(profile,CORE),Integer.toString(area));if(coreOverride!=null)coreFlag=coreOverride;value=BsonLite.withProfileArray(value,"st",Arrays.asList(status(p,area,profile),Boolean.TRUE.equals(coreFlag),locked(profile,area)));value=BsonLite.withProfileDocument(value,"stage",mapStages(p,area,profile));ais=BsonLite.withProfileDocument(ais,key,value);}return BsonLite.withProfileDocument(reply,"ais",ais);}
}
